SELECT 

WHERE e.account_id = #{accountId}
ORDER BY e.detected_at DESC
LIMIT #{limit}

SELECT 

WHERE e.entity_type = 'GROUP'
  AND e.in_use = #{inUse}
  AND e.detected_at >= #{from}
  AND e.detected_at < #{to}
  AND NOT EXISTS (SELECT 1 FROM platforms p
                   WHERE p.id = a.platform_id
                     AND p.pool_monitoring_enabled = TRUE)
ORDER BY e.detected_at DESC
LIMIT #{limit}
